svg.script:
//
document.addEventListener('DOMContentLoaded', () => {
  const NS = 'http://www.w3.org/2000/svg';
  const f = n => (Math.round(n * 10) / 10).toString();
  const $ = id => document.getElementById(id);
  function el(name, attrs, parent) {
    const e = document.createElementNS(NS, name);
    for (const k in attrs) e.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(e);
    return e;
  }

  /* ---------- 常量 ---------- */
  const SPEED = 855;                 // 地面速度 px/s
  const WHEEL_R = 90, GEAR = 38 / 16; // 牙盘/飞轮半径比
  const WHEEL_W = SPEED / WHEEL_R;    // 车轮角速度 rad/s
  const CRANK_W = WHEEL_W / GEAR;     // 曲柄角速度 rad/s
  const CHAIN_V = CRANK_W * 38;       // 链条线速度 px/s
  const BB = { x: 556, y: 580 }, CRANK = 64;
  const HIP = { x: 470, y: 404 }, L1 = 136, L2 = 148;

  /* ---------- 车轮 ---------- */
  function buildWheel(g, cx, cy) {
    el('circle', { cx, cy, r: 83.5, fill: 'none', stroke: '#33333a', 'stroke-width': 13 }, g);
    el('circle', { cx, cy, r: 89.6, fill: 'none', stroke: '#26262c', 'stroke-width': 2.5,
                   'stroke-dasharray': '2.5 7', opacity: .6 }, g);
    el('circle', { cx, cy, r: 79, fill: 'none', stroke: '#45454e', 'stroke-width': 1.5, opacity: .5 }, g);
    el('circle', { cx, cy, r: 76, fill: 'none', stroke: '#d5dbe1', 'stroke-width': 5 }, g);
    el('circle', { cx, cy, r: 73.8, fill: 'none', stroke: '#aab1b9', 'stroke-width': 1 }, g);
    el('circle', { cx, cy, r: 71.5, fill: 'none', stroke: '#f4f7f9', 'stroke-width': 1.5 }, g);
    for (let i = 0; i < 28; i++) {
      const a1 = i * 2 * Math.PI / 28, a2 = a1 + (i % 2 ? 0.14 : -0.14);
      el('line', {
        x1: f(cx + Math.cos(a1) * 8), y1: f(cy + Math.sin(a1) * 8),
        x2: f(cx + Math.cos(a2) * 75), y2: f(cy + Math.sin(a2) * 75),
        stroke: '#c3c9d1', 'stroke-width': 1.6
      }, g);
    }
    el('circle', { cx, cy, r: 9, fill: '#9aa1a9', stroke: '#6b7076', 'stroke-width': 1.5 }, g);
    el('circle', { cx, cy, r: 3.5, fill: '#565b62' }, g);
    const va = -1.1, vx = cx + Math.cos(va) * 76, vy = cy + Math.sin(va) * 76;
    el('rect', { x: f(vx - 2), y: f(vy - 5), width: 4, height: 10, rx: 2,
                 transform: `rotate(${f(va * 180 / Math.PI + 90)} ${f(vx)} ${f(vy)})`, fill: '#666' }, g);
  }
  buildWheel($('rearWheelG'), 430, 560);
  buildWheel($('frontWheelG'), 770, 560);

  /* ---------- 牙盘 ---------- */
  {
    const g = $('chainringG');
    for (let i = 0; i < 28; i++) {
      const a = i * 2 * Math.PI / 28;
      el('circle', { cx: f(BB.x + Math.cos(a) * 38), cy: f(BB.y + Math.sin(a) * 38),
                     r: 2.5, fill: '#9aa1a9' }, g);
    }
    el('circle', { cx: BB.x, cy: BB.y, r: 34, fill: '#c9ced4', stroke: '#7d838a', 'stroke-width': 3 }, g);
    el('circle', { cx: BB.x, cy: BB.y, r: 23, fill: 'none', stroke: '#8f959c', 'stroke-width': 3 }, g);
    [45, 135, 225, 315].forEach(deg => {
      const a = deg * Math.PI / 180;
      el('circle', { cx: f(BB.x + Math.cos(a) * 13), cy: f(BB.y + Math.sin(a) * 13),
                     r: 3.2, fill: '#9aa1a9' }, g);
    });
  }

  /* ---------- 链条 ---------- */
  {
    const c1 = { x: 430, y: 560 }, r1 = 17, c2 = BB, r2 = 38;
    const dx = c2.x - c1.x, dy = c2.y - c1.y, D = Math.hypot(dx, dy);
    const base = Math.atan2(dy, dx), alpha = Math.acos((r2 - r1) / D);
    const P = (c, r, a) => ({ x: c.x + Math.cos(a) * r, y: c.y + Math.sin(a) * r });
    const T3 = P(c2, r2, base - alpha), T1 = P(c2, r2, base + alpha);
    const U1 = P(c1, r1, base + alpha), U3 = P(c1, r1, base - alpha);
    const d = `M ${f(T3.x)} ${f(T3.y)} A ${r2} ${r2} 0 0 1 ${f(T1.x)} ${f(T1.y)} ` +
              `L ${f(U1.x)} ${f(U1.y)} A ${r1} ${r1} 0 1 0 ${f(U3.x)} ${f(U3.y)} Z`;
    $('chainOuter').setAttribute('d', d);
    $('chainDash').setAttribute('d', d);
  }

  /* ---------- 远飞鸟 ---------- */
  function makeBird(parent, x, y, ph) {
    const g = el('g', { transform: `translate(${x} ${y})` }, parent);
    const wl = el('path', { d: 'M 0 0 Q -11 -9 -22 -6 Q -12 -1 0 3 Z', fill: '#6a7a8a' }, g);
    const wr = el('path', { d: 'M 0 0 Q 11 -9 22 -6 Q 12 -1 0 3 Z', fill: '#6a7a8a' }, g);
    el('ellipse', { cx: 0, cy: 0, rx: 5, ry: 3, fill: '#6a7a8a' }, g);
    return { g, wl, wr, x, y, ph };
  }
  const birds = [makeBird($('birdsG'), 300, 170, 0), makeBird($('birdsG'), 760, 225, 2.1)];

  /* ---------- 腿部 IK（鸟腿关节向后弯） ---------- */
  function solve(F, H) {
    let dx = F.x - H.x, dy = F.y - H.y;
    let d = Math.hypot(dx, dy);
    d = Math.min(Math.max(d, Math.abs(L1 - L2) + 0.001), L1 + L2 - 0.001);
    const a = (L1 * L1 - L2 * L2 + d * d) / (2 * d);
    const h = Math.sqrt(Math.max(L1 * L1 - a * a, 0));
    const ux = dx / d, uy = dy / d;
    const mx = H.x + ux * a, my = H.y + uy * a;
    const c1x = mx - uy * h, c1y = my + ux * h;
    const c2x = mx + uy * h, c2y = my - ux * h;
    return c1x < c2x ? { x: c1x, y: c1y } : { x: c2x, y: c2y };
  }
  function limbPath(x1, y1, w1, x2, y2, w2) {
    const dx = x2 - x1, dy = y2 - y1, d = Math.hypot(dx, dy) || 1;
    const nx = -dy / d, ny = dx / d;
    return `M ${f(x1 + nx * w1)} ${f(y1 + ny * w1)} L ${f(x2 + nx * w2)} ${f(y2 + ny * w2)} ` +
           `A ${f(w2)} ${f(w2)} 0 0 1 ${f(x2 - nx * w2)} ${f(y2 - ny * w2)} ` +
           `L ${f(x1 - nx * w1)} ${f(y1 - ny * w1)} A ${f(w1)} ${f(w1)} 0 0 1 ${f(x1 + nx * w1)} ${f(y1 + ny * w1)} Z`;
  }
  function footD(Fx, Fy) {
    return `M ${f(Fx - 12)} ${f(Fy - 13)} L ${f(Fx + 22)} ${f(Fy - 16)} L ${f(Fx + 27)} ${f(Fy - 11)} ` +
           `L ${f(Fx + 31)} ${f(Fy - 6)} L ${f(Fx + 24)} ${f(Fy - 3)} L ${f(Fx + 12)} ${f(Fy - 2)} ` +
           `L ${f(Fx - 4)} ${f(Fy - 3)} Q ${f(Fx - 14)} ${f(Fy - 5)} ${f(Fx - 12)} ${f(Fy - 13)} Z`;
  }
  function toesD(Fx, Fy) {
    return `M ${f(Fx + 22)} ${f(Fy - 16)} L ${f(Fx + 21)} ${f(Fy - 0.5)} ` +
           `M ${f(Fx + 27)} ${f(Fy - 11)} L ${f(Fx + 27.5)} ${f(Fy - 1.5)} ` +
           `M ${f(Fx + 31)} ${f(Fy - 6)} L ${f(Fx + 26)} ${f(Fy + 0.5)}`;
  }
  function updateLeg(L, Fx, Fy, H) {
    const F = { x: Fx, y: Fy };
    const J = solve(F, H);
    L.thigh.setAttribute('d', limbPath(H.x, H.y, 24, J.x, J.y, 10));
    L.shin.setAttribute('d', limbPath(J.x, J.y, 9, F.x - 2, F.y - 4, 5));
    let sc = '';
    [0.3, 0.5, 0.7].forEach(fr => {
      const x = J.x + (F.x - J.x) * fr, y = J.y + (F.y - J.y) * fr;
      const dx = F.x - J.x, dy = F.y - J.y, dd = Math.hypot(dx, dy) || 1;
      const nx = -dy / dd, ny = dx / dd;
      sc += `M ${f(x - nx * 4)} ${f(y - ny * 4)} L ${f(x + nx * 4)} ${f(y + ny * 4)} `;
    });
    L.scales.setAttribute('d', sc);
    L.foot.setAttribute('d', footD(F.x, F.y));
    L.toes.setAttribute('d', toesD(F.x, F.y));
    L.cuff.setAttribute('transform', `translate(${f(H.x)} ${f(H.y)})`);
  }
  const nearLeg = {
    thigh: $('nThigh'), shin: $('nShin'), scales: $('nScales'),
    foot: $('nFoot'), toes: $('nToes'), cuff: $('nCuff')
  };
  const farLeg = {
    thigh: $('fThigh'), shin: $('fShin'), scales: $('fScales'),
    foot: $('fFoot'), toes: $('fToes'), cuff: $('fCuff')
  };

  /* ---------- 围巾 ---------- */
  function scarfPt(k, t) {
    return [600 - 215 * k, 266 + 30 * k + (10 + 18 * k * k) * Math.sin(k * 6 - t * 11), 14 - 8 * k];
  }
  function scarfD(t, off) {
    let d = '';
    for (let i = 0; i <= 12; i++) {
      const p = scarfPt(i / 12, t);
      d += (i ? 'L' : 'M') + f(p[0] + off) + ' ' + f(p[1] - p[2] + off * 0.4) + ' ';
    }
    for (let i = 12; i >= 0; i--) {
      const p = scarfPt(i / 12, t);
      d += 'L' + f(p[0] + off) + ' ' + f(p[1] + p[2] + off * 0.4) + ' ';
    }
    return d + 'Z';
  }
  function scarfExtraD(t) {
    let s = '';
    [0.75, 0.86].forEach(k => {
      const p = scarfPt(k, t);
      s += `M ${f(p[0])} ${f(p[1] - p[2])} L ${f(p[0])} ${f(p[1] + p[2])} `;
    });
    const tip = scarfPt(1, t);
    s += `M ${f(tip[0] - 2)} ${f(tip[1] - 5)} L ${f(tip[0] + 8)} ${f(tip[1] - 8)} ` +
         `M ${f(tip[0] - 1)} ${f(tip[1] - 2)} L ${f(tip[0] + 9)} ${f(tip[1] - 2)} ` +
         `M ${f(tip[0] - 1)} ${f(tip[1] + 2)} L ${f(tip[0] + 9)} ${f(tip[1] + 2)} ` +
         `M ${f(tip[0] - 2)} ${f(tip[1] + 5)} L ${f(tip[0] + 8)} ${f(tip[1] + 8)}`;
    return s;
  }

  /* ---------- 尘土 ---------- */
  const dustG = $('dustG'), dust = [], dustEls = [];
  let dustTimer = 0;
  function updateDust(dt) {
    dustTimer -= dt;
    if (dustTimer <= 0) {
      dustTimer = 0.06 + Math.random() * 0.05;
      if (dust.length < 46)
        dust.push({ x: 412 + Math.random() * 10, y: 642 + Math.random() * 8,
                    vx: -(30 + Math.random() * 80), vy: -(12 + Math.random() * 40),
                    life: 1, s: 3 + Math.random() * 4 });
    }
    for (let i = dust.length - 1; i >= 0; i--) {
      const p = dust[i];
      p.life -= dt * 1.1;
      if (p.life <= 0) { dust.splice(i, 1); continue; }
      p.x += p.vx * dt; p.y += p.vy * dt; p.vy += 26 * dt; p.s += 7 * dt;
    }
    while (dustEls.length < dust.length)
      dustEls.push(el('circle', { fill: '#cfc4ae' }, dustG));
    dustEls.forEach((c, i) => {
      const p = dust[i];
      if (p) {
        c.setAttribute('cx', f(p.x)); c.setAttribute('cy', f(p.y));
        c.setAttribute('r', f(p.s)); c.setAttribute('opacity', f(p.life * 0.32));
        c.removeAttribute('display');
      } else c.setAttribute('display', 'none');
    });
  }

  /* ---------- 视差层 ---------- */
  const layers = [
    { el: $('dashesG'), speed: 848, period: 130 },
    { el: $('ffG'), speed: 420, period: 700 },
    { el: $('nfG'), speed: 848, period: 900 },
    { el: $('treesG'), speed: 260, period: 1200 },
    { el: $('hillFarG'), speed: 55, period: 1500 },
    { el: $('hillNearG'), speed: 130, period: 1100 },
    { el: $('foreG'), speed: 1000, period: 500 }
  ];
  layers.forEach(L => L.d = 0);

  const clouds = [
    { el: $('cl1'), x: 240, y: 120, s: 1.1, v: 9 },
    { el: $('cl2'), x: 620, y: 80, s: 0.8, v: 14 },
    { el: $('cl3'), x: 900, y: 170, s: 1.3, v: 7 },
    { el: $('cl4'), x: 1080, y: 90, s: 0.95, v: 18 },
    { el: $('cl5'), x: 420, y: 200, s: 0.7, v: 12 }
  ];

  const streaks = [
    { el: $('st1'), x: 100, y: 648, len: 90, v: 760 },
    { el: $('st2'), x: 420, y: 706, len: 70, v: 830 },
    { el: $('st3'), x: 660, y: 668, len: 110, v: 700 },
    { el: $('st4'), x: 880, y: 726, len: 60, v: 900 },
    { el: $('st5'), x: 240, y: 740, len: 80, v: 800 }
  ];

  /* ---------- 主循环 ---------- */
  let t = 0, last = performance.now(), paused = false;
  if (window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) paused = true;
  const svg = document.documentElement;
  svg.addEventListener('click', () => { paused = !paused; });

  function update(dt) {
    t += dt;
    const wheelDeg = t * WHEEL_W * 180 / Math.PI;
    const crank = CRANK_W * t;
    const crankDeg = crank * 180 / Math.PI;

    $('rearWheelG').setAttribute('transform', `rotate(${f(wheelDeg)} 430 560)`);
    $('frontWheelG').setAttribute('transform', `rotate(${f(wheelDeg)} 770 560)`);
    $('chainDash').style.strokeDashoffset = f(-((t * CHAIN_V) % 12));

    $('farCrankG').setAttribute('transform', `rotate(${f(crankDeg + 180)} 556 580)`);
    $('nearCrankG').setAttribute('transform', `rotate(${f(crankDeg)} 556 580)`);

    const p1 = { x: BB.x + CRANK * Math.cos(crank), y: BB.y + CRANK * Math.sin(crank) };
    const p2 = { x: BB.x - CRANK * Math.cos(crank), y: BB.y - CRANK * Math.sin(crank) };
    $('farPedalG').setAttribute('transform', `translate(${f(p2.x)} ${f(p2.y)})`);
    $('nearPedalG').setAttribute('transform', `translate(${f(p1.x)} ${f(p1.y)})`);

    const sway = 1.2 * Math.sin(crank), bob = 3.5 * Math.sin(2 * crank + 0.5);
    const pitch = 0.7 * Math.sin(2 * crank + 0.5);
    $('bodyG').setAttribute('transform', `translate(${f(sway)} ${f(bob)}) rotate(${f(pitch)} 466 384)`);
    $('tailG').setAttribute('transform', `rotate(${f(3 * Math.sin(2 * crank + 1.2))} 458 415)`);

    const H = { x: HIP.x + sway, y: HIP.y + bob };
    updateLeg(nearLeg, p1.x, p1.y, H);
    updateLeg(farLeg, p2.x, p2.y, H);

    const hb = -3 * Math.sin(2 * crank + 1.4);
    const tilt = 1.2 * Math.sin(2 * crank + 1.4);
    $('headG').setAttribute('transform', `translate(0 ${f(hb)}) rotate(${f(tilt)} 615 262)`);

    $('wingG').setAttribute('transform', `rotate(${f(2.2 * Math.sin(2 * crank + 0.4))} 572 300)`);

    const phase = t % 4.3;
    const s = phase < 0.16 ? Math.abs(Math.sin(Math.PI * phase / 0.16)) : 0;
    $('lid').setAttribute('transform',
      `translate(674 198) scale(1 ${f(0.05 + 0.95 * s)}) translate(-674 -198)`);
    const px = 1.5 * Math.sin(t * 0.7), py = 1 * Math.sin(t * 1.1 + 2);
    $('pupilG').setAttribute('transform', `translate(${f(px)} ${f(py)})`);

    $('scarfShadow').setAttribute('d', scarfD(t, 3));
    $('scarfMain').setAttribute('d', scarfD(t, 0));
    $('scarfExtra').setAttribute('d', scarfExtraD(t));

    $('shadowB').setAttribute('transform',
      `translate(600 652) scale(${f(1 + 0.015 * Math.sin(2 * crank + 0.5))} 1) translate(-600 -652)`);

    updateDust(dt);

    layers.forEach(L => {
      L.d += L.speed * dt;
      L.el.setAttribute('transform', `translate(${f(-(L.d % L.period))} 0)`);
    });
    clouds.forEach(c => {
      c.x -= c.v * dt;
      if (c.x < -180) c.x = 1250 + Math.random() * 120;
      c.el.setAttribute('transform', `translate(${f(c.x)} ${f(c.y)}) scale(${c.s})`);
    });
    birds.forEach(b => {
      b.x -= (11 + b.ph) * dt;
      if (b.x < -60) { b.x = 1250 + Math.random() * 150; b.y = 150 + Math.random() * 110; }
      const flap = 16 * Math.sin(t * 9 + b.ph);
      b.g.setAttribute('transform', `translate(${f(b.x)} ${f(b.y)})`);
      b.wl.setAttribute('transform', `rotate(${f(-flap)} 0 0)`);
      b.wr.setAttribute('transform', `rotate(${f(flap)} 0 0)`);
    });
    streaks.forEach(s => {
      s.x -= s.v * dt;
      if (s.x < -160) { s.x = 1250 + Math.random() * 150; s.y = 636 + Math.random() * 95; s.len = 50 + Math.random() * 80; }
      s.el.setAttribute('x1', f(s.x));
      s.el.setAttribute('x2', f(s.x + s.len));
      s.el.setAttribute('y1', s.y);
      s.el.setAttribute('y2', s.y);
    });
    $('raysG').setAttribute('transform', `rotate(${f(t * 4)} 170 140)`);
  }

  function frame(now) {
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;
    if (!paused) update(dt);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
});
//
